        var list=new ListBox {Margin=new Thickness(0,0,10,0),DisplayMemberPath="Title"};list.SetResourceReference(Control.BackgroundProperty,"ListBackground");list.SetResourceReference(Control.ForegroundProperty,"PrimaryText");grid.Children.Add(list);
        var body=new TextBlock {TextWrapping=TextWrapping.Wrap,FontSize=14,LineHeight=26,Margin=new Thickness(14,4,4,10)};var diagramHost=new ContentControl {Margin=new Thickness(14,4,4,8)};var article=new StackPanel();article.Children.Add(diagramHost);article.Children.Add(body);var scroll=new ScrollViewer {Content=article,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetColumn(scroll,1);grid.Children.Add(scroll);
        list.SelectionChanged+=(_,_)=>{var topic=list.SelectedItem as Topic;body.Text=topic?.Body ?? "موضوعی پیدا نشد.";diagramHost.Content=topic is null ? null : GuideDiagrams.Create(topic.Title);scroll.ScrollToTop();};
        void Refresh(){list.ItemsSource=Search(search.Text);list.SelectedIndex=list.Items.Count>0?0:-1;if(list.Items.Count==0)body.Text="موضوعی پیدا نشد.";}
        search.TextChanged+=(_,_)=>Refresh();Refresh();Content=root;
    }
}
